        && let Some(r) = self
            .focus
            .and_then(|w| self.canvas.get(&self.group_for(w)?))
            .map(|g| g.rect)
    {
        rect.x = (r.x + r.width + self.gap).min(MAX_COORD - rect.width);
        rect.y = r.y;
    }
    self.canvas.insert(
        group,
        CanvasGroup {
            rect,
            scroll_y: 0.0,
        },
    );
    if activate || self.focus.is_none() {
        self.focus_window(window)
    } else {
        if !self.fullscreen.is_empty() {
            self.reveal_focus();
        }
        Ok(())
