}

fn apply_initial_states(&mut self, id: WindowId) -> Result<(), flux_layout::LayoutError> {
    let requested = self
        .windows
        .get(id)
        .expect("admitted role")
        .initial_maximized;
    let max_result = match self.layout.set_maximized(id, requested) {
        Err(
            flux_layout::LayoutError::InvalidConstraints
            | flux_layout::LayoutError::InvalidGeometry,
        ) => {
            // Hints or viewport may change between the initial configure and
            // first buffer. Keep successful base admission and send normal
            // state rather than trapping the live client in a retry loop.
            self.windows
                .get_mut(id)
                .expect("admitted role")
                .initial_maximized = false;
            self.bump_sequence();
            self.layout.set_maximized(id, false)
        }
        result => result,
    };
    max_result?;
    let requested = self
        .windows
        .get(id)
        .expect("admitted role")
        .initial_fullscreen;
    match self.layout.set_fullscreen(id, requested) {
        Err(
            flux_layout::LayoutError::InvalidConstraints
            | flux_layout::LayoutError::InvalidGeometry,
        ) => {
            self.windows
                .get_mut(id)
                .expect("admitted role")
                .initial_fullscreen = false;
            self.bump_sequence();
            self.layout.set_fullscreen(id, false)
        }
        result => result,
    }
}

fn cancel_window_grab(&mut self, id: WindowId) {
    let Some(pointer) = self.seat.get_pointer() else {
        return;
    };
    let owned = pointer
        .with_grab(|_, grab| {
            grab.downcast_ref::<crate::grabs::MoveSurfaceGrab>()
                .is_some_and(|grab| grab.window_id() == id)
                || grab
                    .downcast_ref::<crate::grabs::ResizeSurfaceGrab>()
                    .is_some_and(|grab| grab.window_id() == id)
        })
        .unwrap_or(false);
    if owned {
        pointer.unset_grab(
            self,
            SERIAL_COUNTER.next_serial(),
            smithay::backend::input::InputTime::now(),
        );
    }
}

fn owns_click_grab(&self, id: WindowId) -> bool {
    use smithay::reexports::wayland_server::Resource;
    let Some(top) = self.windows.get(id).and_then(|item| item.window.toplevel()) else {
        return false;
    };
    let Some(pointer) = self.seat.get_pointer() else {
        return false;
    };
    pointer
        .with_grab(|_, grab| grab.is::<smithay::input::pointer::ClickGrab<Self>>())
        .unwrap_or(false)
        && pointer
            .grab_start_data()
            .and_then(|data| data.focus)
            .is_some_and(|(focus, _)| focus.id().same_client_as(&top.wl_surface().id()))
}

