/// PopupGrab. Detach every subtree when its root leaves the scene so a later
/// remap cannot resurrect old popups. Collect before mutating the tree;
/// dismiss_popup sends popup_done to descendants before their parent.
fn dismiss_root_popups(surface: &WlSurface) {
    if !surface.alive() {
        return;
    }
    let popups: Vec<_> = PopupManager::popups_for_surface(surface)
        .map(|(popup, _)| popup)
        .collect();
    for popup in popups {
        // An earlier ancestor dismissal may already have detached this node.
        // The pinned manager treats an absent subtree as a no-op.
        let _ = PopupManager::dismiss_popup(surface, &popup);
    }
}

pub fn remove_toplevel(&mut self, surface: &WlSurface) {
    let Some(id) = self.window_id(surface) else {
        return;
    };
    Self::dismiss_root_popups(surface);
    if let Some(item) = self.windows.remove(id) {
        self.cancel_window_grab(id);
        self.space.unmap_elem(&item.window);
        if item.mapped {
            let _ = self.layout.remove(id);
        }
        self.stats.destroyed += 1;
        self.bump_sequence();
        tracing::info!(%id, "toplevel_destroyed");
        self.relayout();
        self.restore_keyboard_focus();
    }
}

/// Called after Smithay has applied buffer/subsurface commit state.
pub fn commit_window(&mut self, root: &WlSurface) {
    let Some(id) = self.window_id(root) else {
        return;
    };
    let has_buffer =
        smithay::backend::renderer::utils::with_renderer_surface_state(root, |s| {
            s.buffer().is_some()
        })
        .unwrap_or(false);
    if !has_buffer
        && let Some(top) = self
            .windows
            .get(id)
            .filter(|item| item.initial_maximized && !item.mapped)
            .and_then(|item| item.window.toplevel())
            .cloned()
    {
        match self.layout.maximize_size(self.constraints_for(root)) {
            Ok(size) => top.with_pending_state(|s| {
                s.size = Some((size.width.round() as i32, size.height.round() as i32).into())
            }),
            Err(_) => {
                self.windows
                    .get_mut(id)
                    .expect("live role")
                    .initial_maximized = false;
                self.bump_sequence();
                top.with_pending_state(|s| {
                    s.size=None;
                    s.states.unset(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Maximized);
                });
            }
        }
    }
    if !has_buffer
        && let Some(top) = self
            .windows
            .get(id)
            .filter(|item| item.initial_fullscreen && !item.mapped)
            .and_then(|item| item.window.toplevel())
            .cloned()
    {
        match self.layout.fullscreen_size(self.constraints_for(root)) {
            Ok(size) => top.with_pending_state(|s| {
                s.size=Some((size.width.round() as i32,size.height.round() as i32).into());
                s.states.set(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Fullscreen);
                s.states.unset(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Maximized);
            }),
            Err(_) => {
                self.windows.get_mut(id).expect("live role").initial_fullscreen=false;
                self.bump_sequence();
                top.with_pending_state(|s|s.states.unset(smithay::reexports::wayland_protocols::xdg::shell::server::xdg_toplevel::State::Fullscreen));
            }
        }
    }
    let item = self
        .windows
        .get_mut(id)
        .expect("live lookup within one dispatch");
    let was_buffered = item.buffered;
    item.buffered = has_buffer;
    if !has_buffer {
        item.admission_error = None;
    }
    item.window.on_commit();
    if has_buffer
        && let Some(top) = item.window.toplevel()
        && !crate::configure::valid_configured_size(top, item.window.geometry().size)
    {
        let top = top.clone();
        self.reject_invalid_configured_size(&top);
        return;
    }
    let was_mapped = item.mapped;
    let window = item.window.clone();
    if has_buffer && !was_mapped {
        let activate = !self.seat.get_keyboard().is_some_and(|k| k.is_grabbed());
